<?php
require_once __DIR__.'/auth.php'; require_roles(['Employee']); $u=current_user(); if(empty($u['employee_id'])){http_response_code(403);exit('Your account is not linked to an employee record. Contact HR.');}$eid=(int)$u['employee_id'];
$s=$conn->prepare('SELECT employee_code,full_name,email,department,designation,status,joining_date FROM employees WHERE id=?');$s->bind_param('i',$eid);$s->execute();$emp=$s->get_result()->fetch_assoc();$s->close();if(!$emp){http_response_code(404);exit('Linked employee record was not found.');}
$s=$conn->prepare('SELECT leave_type,start_date,end_date,status,created_at FROM leave_requests WHERE employee_id=? ORDER BY created_at DESC LIMIT 10');$s->bind_param('i',$eid);$s->execute();$leaves=$s->get_result();$s=$conn->prepare('SELECT title,description,priority,status,due_date FROM hr_tasks WHERE employee_id=? ORDER BY FIELD(status,\'To Do\',\'In Progress\',\'Done\'),due_date');$s->bind_param('i',$eid);$s->execute();$tasks=$s->get_result();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My workspace · HRMS</title><link rel="stylesheet" href="assets.css"></head><body><header><h1>My workspace</h1><p>Welcome, <?=h($emp['full_name'])?>. This view only shows your linked records.</p></header><?php include 'nav.php';?><main><div class="grid"><section class="panel col-4"><h2>My profile</h2><p><strong><?=h($emp['full_name'])?></strong></p><p><?=h($emp['employee_code'])?></p><p><?=h($emp['designation'])?> · <?=h($emp['department'])?></p><p><?=h($emp['email'])?></p><p>Status: <?=h($emp['status'])?></p></section><section class="panel col-8"><h2>My leave history</h2><div class="table-wrap"><table><thead><tr><th>Type</th><th>Dates</th><th>Status</th></tr></thead><tbody><?php while($l=$leaves->fetch_assoc()):?><tr><td><?=h($l['leave_type'])?></td><td><?=h($l['start_date'])?> – <?=h($l['end_date'])?></td><td><?=h($l['status'])?></td></tr><?php endwhile;?></tbody></table></div><a class="btn" href="leave.php">Open leave requests</a></section><section class="panel col-12"><h2>My assigned tasks</h2><div class="table-wrap"><table><thead><tr><th>Task</th><th>Priority</th><th>Due</th><th>Status</th></tr></thead><tbody><?php while($t=$tasks->fetch_assoc()):?><tr><td><strong><?=h($t['title'])?></strong><br><?=h($t['description'])?></td><td><?=h($t['priority'])?></td><td><?=h($t['due_date']??'—')?></td><td><?=h($t['status'])?></td></tr><?php endwhile;?></tbody></table></div><a class="btn" href="tasks.php">Open task board</a></section></div></main></body></html>